import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.D9E58p8B.js";const p=JSON.parse('{"title":"Privacy","description":"","frontmatter":{"title":"Privacy"},"headers":[],"relativePath":"en/guide/confidentialite.md","filePath":"en/guide/confidentialite.md"}'),n={name:"en/guide/confidentialite.md"};function s(r,e,c,h,l,d){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h1><h2 id="everything-is-local" tabindex="-1">Everything is local <a class="header-anchor" href="#everything-is-local" aria-label="Permalink to &quot;Everything is local&quot;">​</a></h2><p>Daimon runs on your computer. It has no telemetry and no account and collects nothing. It calls no AI model itself and sends nothing to ArboRithm.</p><p>Its only connection to the Internet is the update check, served by GitHub Releases. If the GitHub CLI tool (<code>gh</code>) is installed and signed in, this check also asks it, using your own session, whether your account has access to ArboRithm&#39;s restricted update channel: nothing is transmitted to ArboRithm.</p><h2 id="this-documentation-site" tabindex="-1">This documentation site <a class="header-anchor" href="#this-documentation-site" aria-label="Permalink to &quot;This documentation site&quot;">​</a></h2><p>This site measures its audience with Matomo, hosted by ArboRithm, <strong>without cookies</strong>: it counts page views and stores nothing on your device. This applies to this site only; the Daimon application itself sends nothing to ArboRithm.</p><h2 id="what-your-ai-client-does" tabindex="-1">What your AI client does <a class="header-anchor" href="#what-your-ai-client-does" aria-label="Permalink to &quot;What your AI client does&quot;">​</a></h2><p>What your AI client does with what it perceives through Daimon (a screenshot, a window&#39;s text) is between you and that client&#39;s provider. Set the <a href="./plafond-et-exclusions.html">ceiling</a> and your exclusions accordingly.</p><h2 id="secrets" tabindex="-1">Secrets <a class="header-anchor" href="#secrets" aria-label="Permalink to &quot;Secrets&quot;">​</a></h2><ul><li>Password fields are masked in what the AI reads from the accessibility tree.</li><li>In screenshots, they are blacked out too when the accessibility tree is readable (on macOS, once the Accessibility permission is granted). This is a best-effort pass: the result says so when it could not take place.</li><li>Your own <a href="./plafond-et-exclusions.html#les-exclusions">exclusions</a> come on top: refused applications, blacked-out areas, removed titles.</li></ul><h2 id="the-activity-log" tabindex="-1">The activity log <a class="header-anchor" href="#the-activity-log" aria-label="Permalink to &quot;The activity log&quot;">​</a></h2><p>Each Mains (Hands) action is recorded, on your computer, in a log where any tampering is detectable (each entry is chained to the previous one). It records what was done and on what, <strong>never the text typed</strong>. The <strong>Journal d&#39;activité</strong> (Activity log) button in the panel opens its folder.</p><h2 id="where-the-files-are" tabindex="-1">Where the files are <a class="header-anchor" href="#where-the-files-are" aria-label="Permalink to &quot;Where the files are&quot;">​</a></h2><p>The settings (<code>exclusions.yaml</code>, <code>update.yaml</code>) are in the configuration folder, which the panel opens. The default data folder is <code>~/Library/Application Support/Daimon</code> on macOS and <code>%APPDATA%\\Daimon</code> on Windows; the configuration is in <code>config</code> there and the logs in <code>logs</code>.</p>',14)])])}const m=t(n,[["render",s]]);export{p as __pageData,m as default};
